import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Navbar.css';

function Navbar({ cartCount, onCartClick, user, onLogout }) {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const navigate = useNavigate();

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-[var(--cream)]/95 backdrop-blur-md border-b-4 border-[var(--saffron)] shadow-xl" style={{ boxShadow: '0 4px 20px rgba(128,0,32,0.15)' }}>
      <div className="max-w-7xl mx-auto px-4 flex items-center justify-between h-16">
        <Link to="/" className="flex items-center gap-2 no-underline" onClick={() => setIsMenuOpen(false)}>
          <span className="text-3xl drop-shadow-lg" style={{ filter: 'drop-shadow(0 2px 4px rgba(212,160,23,0.4))' }}>🍛</span>
          <div className="flex flex-col">
            <span className="font-serif font-bold text-lg text-red-800 leading-tight">Riddhi Siddhi</span>
            <span className="text-xs text-gray-500">Modak Farsan</span>
          </div>
        </Link>

        <button className="md:hidden flex flex-col gap-1.5 bg-none border-none cursor-pointer p-1" onClick={() => setIsMenuOpen(!isMenuOpen)}>
          <span className={`block w-6 h-0.5 bg-red-800 transition-all ${isMenuOpen ? 'rotate-45 translate-y-1.5' : ''}`}></span>
          <span className={`block w-6 h-0.5 bg-red-800 transition-all ${isMenuOpen ? 'opacity-0' : ''}`}></span>
          <span className={`block w-6 h-0.5 bg-red-800 transition-all ${isMenuOpen ? '-rotate-45 -translate-y-1.5' : ''}`}></span>
        </button>

        <div className={`md:flex items-center gap-1 ${isMenuOpen ? 'flex flex-col absolute top-16 left-0 right-0 bg-white p-4 shadow-xl border-t' : 'hidden'}`}>
          <Link to="/" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>🏠 Home</Link>
          <Link to="/category/Dry Snacks" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>🥨 Dry Snacks</Link>
          <Link to="/category/Namkeen" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>🥟 Namkeen</Link>
          <Link to="/category/Sweets" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>🍬 Sweets</Link>
          <Link to="/category/Wet Sweets" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>🍮 Fresh Sweets</Link>
          {user ? (
            <>
              <Link to="/dashboard" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>📋 Orders</Link>
              <button className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition bg-none border-none cursor-pointer" onClick={() => { onLogout(); setIsMenuOpen(false); navigate('/'); }}>🚪 Logout</button>
            </>
          ) : (
            <Link to="/checkout" className="px-3 py-2 text-sm font-medium text-gray-700 hover:bg-red-50 hover:text-red-700 rounded-lg transition" onClick={() => setIsMenuOpen(false)}>👤 Login</Link>
          )}
        </div>

        <button className="relative bg-none border-none cursor-pointer p-2 rounded-full hover:bg-red-50 transition" onClick={onCartClick}>
          <span className="text-xl">🛒</span>
          {cartCount > 0 && (
            <span className="absolute -top-0.5 -right-0.5 bg-red-700 text-white text-xs font-bold w-5 h-5 rounded-full flex items-center justify-center shadow">{cartCount}</span>
          )}
        </button>
      </div>
    </nav>
  );
}

export default Navbar;
